var mgr = SecondaryMissionManager
var p = GameState.get_active_player()
# Own the setup end-to-end: this scenario is about the discard gate, so it
# builds the hand itself rather than depending on whatever the fixture's
# Command-phase entry left in the deck (iss063b covers that bootstrap).
if not mgr.is_initialized(p):
	mgr.setup_tactical_deck(p)
var st = mgr._player_state[str(p)]
st["mode"] = "fixed"
st["active"] = []
for mid in ["engage_on_all_fronts", "assassination"]:
	st["active"].append(mgr._create_active_mission(SecondaryMissionData.get_mission_by_id(mid)))
var bw = float(GameState.state.get("board", {}).get("size", {}).get("width", 44))
var bh = float(GameState.state.get("board", {}).get("size", {}).get("height", 60))
var pts = [Vector2(bw * 0.15, bh * 0.15), Vector2(bw * 0.85, bh * 0.15), Vector2(bw * 0.15, bh * 0.85)]
var placed = 0
for uid in GameState.state["units"].keys():
	if placed >= 3:
		break
	var u = GameState.state["units"][uid]
	if int(u.get("owner", 0)) != p:
		continue
	var models = u.get("models", [])
	if models.size() == 0:
		continue
	var px = Vector2(Measurement.inches_to_px(pts[placed].x), Measurement.inches_to_px(pts[placed].y))
	for m in models:
		m["position"] = {"x": px.x, "y": px.y}
		m["alive"] = true
	placed += 1
return placed

var p = GameState.get_active_player()
var st = SecondaryMissionManager._player_state[str(p)]
return "%s:%d" % [str(st["active"][0]["id"]), int(st["active"][0].get("vp_scored_this_turn", 0))]

var states = []
var stack = [tree.root]
while stack.size() > 0:
	var n = stack.pop_back()
	for c in n.get_children():
		stack.append(c)
	if n is Button and str(n.text).begins_with("Discard"):
		states.append(bool(n.disabled))
return str(states)

var sc = tree.root.get_node_or_null("Main/HUD_Right/VBoxContainer/ScoringScrollContainer")
if sc == null:
	return "no scroll container"
sc.scroll_vertical = 100000
return sc.scroll_vertical

var mgr = SecondaryMissionManager
var fixed_key = ""
for k in ["1", "2"]:
	if str(mgr._player_state[k].get("mode", "")) == "fixed":
		fixed_key = k
if fixed_key == "":
	return "no fixed player"
var ids = []
for m in mgr._player_state[fixed_key]["active"]:
	ids.append(str(m["id"]))
var inst = PhaseManager.get_current_phase_instance()
var offers = 0
if inst != null and inst.has_method("get_available_actions"):
	for a in inst.get_available_actions():
		if str(a.get("type", "")) == "DISCARD_SECONDARY":
			offers += 1
return "%s discard_offers=%d" % [str(ids), offers]

var mgr = SecondaryMissionManager
var p = GameState.get_active_player()
# Own the setup end-to-end: this scenario is about the discard gate, so it
# builds the hand itself rather than depending on whatever the fixture's
# Command-phase entry left in the deck (iss063b covers that bootstrap).
if not mgr.is_initialized(p):
	mgr.setup_tactical_deck(p)
var st = mgr._player_state[str(p)]
st["mode"] = "tactical"
st["active"] = []
for mid in ["engage_on_all_fronts", "assassination"]:
	st["active"].append(mgr._create_active_mission(SecondaryMissionData.get_mission_by_id(mid)))
var bw = float(GameState.state.get("board", {}).get("size", {}).get("width", 44))
var bh = float(GameState.state.get("board", {}).get("size", {}).get("height", 60))
var pts = [Vector2(bw * 0.15, bh * 0.15), Vector2(bw * 0.85, bh * 0.15), Vector2(bw * 0.15, bh * 0.85)]
var placed = 0
for uid in GameState.state["units"].keys():
	if placed >= 3:
		break
	var u = GameState.state["units"][uid]
	if int(u.get("owner", 0)) != p:
		continue
	var models = u.get("models", [])
	if models.size() == 0:
		continue
	var px = Vector2(Measurement.inches_to_px(pts[placed].x), Measurement.inches_to_px(pts[placed].y))
	for m in models:
		m["position"] = {"x": px.x, "y": px.y}
		m["alive"] = true
	placed += 1
return "p%d placed=%d" % [p, placed]

var p = GameState.get_active_player()
var st = SecondaryMissionManager._player_state[str(p)]
var ids = []
for m in st["active"]:
	ids.append(str(m["id"]))
return str(ids)

var inst = PhaseManager.get_current_phase_instance()
var out = []
for a in inst.get_available_actions():
	if str(a.get("type", "")) == "DISCARD_SECONDARY":
		out.append(int(a.get("mission_index", -1)))
return str(out)

var st = SecondaryMissionManager._player_state["1"]
var ids = []
for m in st["active"]:
	ids.append(str(m["id"]))
return str(ids)
